	}
	time.Sleep(50 * time.Millisecond)

	startApplied := victim.getLastApplied()
	startRestores := victimFSM.restoreCount()
	startLastLogIdx, startLastLogTerm := victim.getLastLog()
	startSnapIdx, _ := victim.getLastSnapshot()

