	deadline := time.Now().Add(d)
	var last *Raft
	streak := 0
	for time.Now().Before(deadline) {
		var cur *Raft
		n := 0
		for _, r := range rs {
			if r.getState() == Leader {
				cur = r
				n++
			}
		}
		if n == 1 && cur == last {
			streak++
			if streak >= 3 {
				return cur
			}
		} else {
			last = cur
			streak = 0
		}
		time.Sleep(20 * time.Millisecond)
	}
	return nil
}

